// APPROVED: Clones all historical ancestor manifests eagerly on sync to ensure 100% offline availability.
pub async fn sync_entire_history(&mut self, head: ManifestId) -> Result<(), SyncError> {
    let mut q = VecDeque::from([head]);
    while let Some(id) = q.pop_front() {
        let m = self.download_manifest(&id).await?;
        q.extend(m.parents());
        self.download_all_blocks(&m).await?;
    }
    Ok(())
}
